var folder="Assets/Art Resources/Environment/FactoryRoads/DirtSample48m";
UnityEditor.AssetDatabase.Refresh();
foreach(var path0 in System.IO.Directory.GetFiles(folder+"/Textures","*.png")){var path=path0.Replace('\\','/');var ti=(UnityEditor.TextureImporter)UnityEditor.AssetImporter.GetAtPath(path);bool normal=path.Contains("Normal");ti.textureType=normal?UnityEditor.TextureImporterType.NormalMap:UnityEditor.TextureImporterType.Default;ti.sRGBTexture=path.Contains("BaseColor");ti.alphaSource=UnityEditor.TextureImporterAlphaSource.FromInput;ti.alphaIsTransparency=path.Contains("BaseColor");ti.wrapModeU=UnityEngine.TextureWrapMode.Clamp;ti.wrapModeV=UnityEngine.TextureWrapMode.Repeat;ti.maxTextureSize=2048;ti.mipmapEnabled=true;ti.anisoLevel=8;ti.textureCompression=UnityEditor.TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();}
var mat=new UnityEngine.Material(UnityEngine.Shader.Find("HDRP/Decal"));mat.name="G87 Dirt02 Continuous Road";
mat.SetTexture("_BaseColorMap",UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture2D>(folder+"/Textures/_BaseColorMap.png"));mat.SetTexture("_NormalMap",UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture2D>(folder+"/Textures/_NormalMap.png"));mat.SetTexture("_MaskMap",UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture2D>(folder+"/Textures/_MaskMap.png"));
