var scene=UnityEditor.SceneManagement.EditorSceneManager.NewPreviewScene();try{var root=new UnityEngine.GameObject("Factory Dirt Road Sample 48m");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root,scene);var plane=UnityEngine.GameObject.CreatePrimitive(UnityEngine.PrimitiveType.Plane);plane.name="Surrounding Ground";plane.transform.SetParent(root.transform,false);plane.transform.localScale=new UnityEngine.Vector3(1.2f,1,5.4f);plane.GetComponent<UnityEngine.Renderer>().sharedMaterial=ground;var obj=new UnityEngine.GameObject("Dirt Road 6m x 48m");obj.transform.SetParent(root.transform,false);obj.transform.localPosition=new UnityEngine.Vector3(0,.05f,0);obj.transform.localRotation=UnityEngine.Quaternion.Euler(90,0,0);var dp=obj.AddComponent<UnityEngine.Rendering.HighDefinition.DecalProjector>();dp.material=mat;dp.size=new UnityEngine.Vector3(6,48,.5f);dp.uvScale=new UnityEngine.Vector2(1,4);dp.drawDistance=200;UnityEditor.PrefabUtility.SaveAsPrefabAsset(root,folder+"/FactoryDirtRoad48m.prefab");}finally{UnityEditor.SceneManagement.EditorSceneManager.ClosePreviewScene(scene);}UnityEditor.AssetDatabase.SaveAssets();return new{prefab=folder+"/FactoryDirtRoad48m.prefab",width=6,length=48,repeats=4,dirty=UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty};
